static void w_html_tab(const ztab *t, int hdr, sb_t *b) { sb_s(b, "<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<title>Tabla</title>\n<style>body{font-family:Helvetica,Arial,sans-serif;margin:1.5em}table{border-collapse:collapse}td,th{border:1px solid #cbd5e1;padding:.3em .6em}th{background:#fef3c7}tr:nth-child(even) td{background:#f8fafc}</style>\n</head>\n<body>\n<table>\n");
    for (int i = 0; i < t->nr; i++) { sb_s(b, "<tr>"); for (int j = 0; j < t->nc; j++) { const char *c = cell(t, i, j), *tg = hdr && !i ? "th" : "td"; sb_f(b, "<%s>", tg); sb_esc(b, c, strlen(c)); sb_f(b, "</%s>", tg); } sb_s(b, "</tr>\n"); } sb_s(b, "</table>\n</body>\n</html>\n"); }
static int u8len(const char *s) { int n = 0; for (; *s; s++) if (((u8)*s & 0xC0) != 0x80) n++; return n; }
static void md_cell(sb_t *b, const char *s) { for (; *s; s++) { if (*s == '|') sb_s(b, "\\|"); else if (*s == '\n') sb_s(b, " "); else sb_add(b, s, 1); } }
static void w_md_tab(const ztab *t, int hdr, sb_t *b) { for (int i = 0; i < t->nr || i == 0; i++) { sb_s(b, "|"); for (int j = 0; j < MAX(1, t->nc); j++) { sb_s(b, " "); if (i < t->nr) md_cell(b, cell(t, i, j)); sb_s(b, " |"); } sb_s(b, "\n"); if (i == 0) { sb_s(b, "|"); for (int j = 0; j < MAX(1, t->nc); j++) sb_s(b, is_num(cell(t, 1, j)) ? " ---: |" : " --- |"); sb_s(b, "\n"); } } }
static void w_txt_tab(const ztab *t, sb_t *b) { int *w = calloc(t->nc + 1, sizeof(int)); for (int i = 0; i < t->nr; i++) for (int j = 0; j < t->nc; j++) w[j] = MAX(w[j], MIN(60, u8len(cell(t, i, j))));
    for (int i = 0; i < t->nr; i++) { for (int j = 0; j < t->nc; j++) { const char *c = cell(t, i, j); int l = u8len(c), num = is_num(c); if (num) for (int k = l; k < w[j]; k++) sb_s(b, " "); sb_s(b, c); if (j + 1 < t->nc) { if (!num) for (int k = l; k < w[j]; k++) sb_s(b, " "); sb_s(b, "  "); } } sb_s(b, "\n"); } free(w); }
static int tab_read(const char *path, const u8 *d, long n, char dl, ztab *t, char *err) {
    memset(t, 0, sizeof *t); if (z_ends(path, ".xlsx")) return xlsx_read(d, n, t, err); char *s = malloc(n + 1); memcpy(s, d, n); s[n] = 0; int r = 0;
    if (z_ends(path, ".json")) r = json_read(s, t, err); else if (z_ends(path, ".xml")) r = xml_read(s, t, err); else if (z_ends(path, ".yaml") || z_ends(path, ".yml")) r = yaml_read(s, t, err); else csv_read(s, z_ends(path, ".tsv") || z_ends(path, ".tab") ? '\t' : dl, t);
    free(s); return r; }
